struct Widget { /* ... */ };

// 1. Unique Ownership (Non-copyable, Move semantics)
// Use std::make_unique for exception safety
auto p_u = std::make_unique<Widget>();
p_u->data = 10;

// Ownership transfer (move only)
auto p_u2 = std::move(p_u);
// Resource automatically freed when p_u2 goes out of scope

// 2. Shared Ownership (Reference counted)
auto p_s1 = std::make_shared<Widget>();
auto p_s2 = p_s1; // Reference count increases (now 2)

// 3. Weak Pointer (Non-owning observer)
std::weak_ptr<Widget> p_w = p_s1;

if (auto locked = p_w.lock()) {
    // Access is safe, temporary shared ownership acquired
}

p_s2.reset();
p_s1.reset(); // Resource is now freed (count reached 0)
